#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct HeaderConfig {
    pub name: String,
    pub value: String,
}

/// Redirection configuration for alias or auxiliary domains.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct DomainRedirectConfig {
    pub domain: String,
    pub target: String,
    pub status_code: u16,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct StaticVhostContext {
    pub site_id: String,
    pub primary_domain: String,
    pub alias_domains: Vec<String>,
    pub redirects: Vec<DomainRedirectConfig>,
    pub docroot: String,
    pub log_dir: String,
    pub snippets_dir: String,
    pub index_files: Option<String>,
    pub spa_fallback: bool,
    pub has_ssl: bool,
    pub ssl_cert: Option<String>,
    pub ssl_key: Option<String>,
    pub force_https: bool,
    pub ocsp_stapling: bool,
    pub custom_headers: Vec<HeaderConfig>,
    #[serde(default)]
    pub site_rules_block: Option<String>,
}

/// Presets for PHP web applications.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, Default)]
#[serde(rename_all = "lowercase")]
pub enum PhpPreset {
    #[default]
    Generic,
    Wordpress,
    Laravel,
    Custom,
}

impl PhpPreset {
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Generic => "generic",
            Self::Wordpress => "wordpress",
            Self::Laravel => "laravel",
            Self::Custom => "custom",
        }
    }

    pub fn parse(s: &str) -> Option<Self> {
        match s.to_ascii_lowercase().as_str() {
            "generic" | "default" | "standard" => Some(Self::Generic),
            "wordpress" | "wp" => Some(Self::Wordpress),
            "laravel" => Some(Self::Laravel),
            "custom" => Some(Self::Custom),
            _ => None,
        }
    }
}

