    #[test]
    fn test_nodejs_vhost_ssrf_and_injection_guard() {
        let renderer = NginxTemplateRenderer::new();
        let base_ctx = NodejsVhostContext {
            site_id: "site_guard".to_string(),
            primary_domain: "node-guard.test".to_string(),
            alias_domains: vec![],
            redirects: vec![],
            docroot: None,
            log_dir: "/var/log/panel/user/site".to_string(),
            snippets_dir: "/etc/panel/nginx/snippets".to_string(),
            has_ssl: false,
            ssl_cert: None,
            ssl_key: None,
            force_https: false,
            ocsp_stapling: false,
            custom_headers: vec![],
            upstream_url: "http://127.0.0.1:20000".to_string(),
            upload_max_size: None,
            static_assets_enabled: false,
            proxy_connect_timeout: None,
            proxy_send_timeout: None,
            proxy_read_timeout: None,
            proxy_buffering: None,
            site_rules_block: None,
        };

        // 1. SSRF Cloud Metadata IP rejected
        let ssrf_metadata = NodejsVhostContext {
            upstream_url: "http://169.254.169.254:80/latest/meta-data".to_string(),
            ..base_ctx.clone()
        };
        assert!(renderer.render_nodejs(&ssrf_metadata).is_err());

        // 2. External non-loopback host rejected by default
        let external_host = NodejsVhostContext {
            upstream_url: "http://example.org:3000".to_string(),
            ..base_ctx.clone()
        };
        assert!(renderer.render_nodejs(&external_host).is_err());

        // 3. Newline injection in upstream rejected
        let newline_inject = NodejsVhostContext {
            upstream_url: "http://127.0.0.1:20000\r\nproxy_pass http://evil.com;".to_string(),
            ..base_ctx.clone()
        };
        assert!(renderer.render_nodejs(&newline_inject).is_err());

        // 4. Unix socket accepted
        let unix_sock = NodejsVhostContext {
            upstream_url: "http://unix:/run/panel/node/site-1.sock:".to_string(),
            ..base_ctx.clone()
        };
        assert!(renderer.render_nodejs(&unix_sock).is_ok());
    }

