    #[test]
    fn test_python_vhost_validation_security() {
        let renderer = NginxTemplateRenderer::new();
        let base_ctx = PythonVhostContext {
            site_id: "site_py_guard".to_string(),
            primary_domain: "py-guard.test".to_string(),
            alias_domains: vec![],
            redirects: vec![],
            unix_socket: "/run/panel/python/site-1.sock".to_string(),
            log_dir: "/var/log/panel/user/site".to_string(),
            snippets_dir: "/etc/panel/nginx/snippets".to_string(),
            has_ssl: false,
            ssl_cert: None,
            ssl_key: None,
            force_https: false,
            ocsp_stapling: false,
            custom_headers: vec![],
            static_url: None,
            static_dir: None,
            media_url: None,
            media_dir: None,
            upload_max_size: None,
            proxy_connect_timeout: None,
            proxy_send_timeout: None,
            proxy_read_timeout: None,
            proxy_buffering: None,
            site_rules_block: None,
        };

        // 1. Relative socket path rejected
        let rel_sock = PythonVhostContext {
            unix_socket: "relative/path.sock".to_string(),
            ..base_ctx.clone()
        };
        assert!(renderer.render_python(&rel_sock).is_err());

        // 2. Traversal socket path rejected
        let trav_sock = PythonVhostContext {
            unix_socket: "/run/panel/../etc/passwd.sock".to_string(),
            ..base_ctx.clone()
        };
        assert!(renderer.render_python(&trav_sock).is_err());

        // 3. Newline in socket path rejected
        let newline_sock = PythonVhostContext {
            unix_socket: "/run/panel/sock\r\nproxy_pass http://evil.com;".to_string(),
            ..base_ctx.clone()
        };
        assert!(renderer.render_python(&newline_sock).is_err());

        // 4. Valid unix: prefix normalized
        let prefix_sock = PythonVhostContext {
            unix_socket: "unix:/run/panel/python/site-99.sock".to_string(),
            ..base_ctx.clone()
        };
        let conf = renderer
            .render_python(&prefix_sock)
            .expect("valid unix prefix");
        assert!(conf.contains("proxy_pass http://unix:/run/panel/python/site-99.sock;"));
    }

    #[test]
    fn test_proxy_vhost_rendering_loopback() {
        let renderer = NginxTemplateRenderer::new();
        let ctx = ReverseProxyVhostContext {
            site_id: "site_proxy_1".to_string(),
            primary_domain: "proxy.example.com".to_string(),
            alias_domains: vec!["api.proxy.example.com".to_string()],
            redirects: vec![],
            log_dir: "/var/log/panel/user/proxy.example.com".to_string(),
            snippets_dir: "/etc/panel/nginx/snippets".to_string(),
            has_ssl: true,
            ssl_cert: Some("/etc/ssl/certs/proxy.crt".to_string()),
            ssl_key: Some("/etc/ssl/private/proxy.key".to_string()),
            force_https: true,
            ocsp_stapling: true,
            upstream_url: "http://127.0.0.1:8080".to_string(),
            preserve_host: true,
            custom_host_header: None,
            websocket_support: true,
            upload_max_size: Some("64M".to_string()),
            proxy_connect_timeout: Some("30s".to_string()),
            proxy_send_timeout: Some("30s".to_string()),
            proxy_read_timeout: Some("90s".to_string()),
            proxy_buffering: Some("off".to_string()),
            custom_headers: vec![HeaderConfig {
                name: "X-Served-By".to_string(),
                value: "Nusa-Proxy".to_string(),
            }],
            custom_request_headers: vec![HeaderConfig {
                name: "X-Upstream-Auth".to_string(),
                value: "SecretKey".to_string(),
            }],
            proxy_ssl_server_name: false,
            allow_external_upstream: false,
            site_rules_block: None,
        };

        let conf = renderer.render_proxy(&ctx).expect("render proxy vhost");
        assert!(conf.contains("proxy_pass http://127.0.0.1:8080;"));
        assert!(conf.contains("proxy_set_header Upgrade $http_upgrade;"));
        assert!(conf.contains("proxy_set_header Connection $connection_upgrade;"));
        assert!(conf.contains("proxy_set_header Host $host;"));
        assert!(conf.contains("proxy_set_header X-Upstream-Auth \"SecretKey\";"));
        assert!(conf.contains("add_header X-Served-By \"Nusa-Proxy\" always;"));
        assert!(conf.contains("client_max_body_size 64M;"));
        assert!(conf.contains("proxy_connect_timeout 30s;"));
        assert!(conf.contains("proxy_read_timeout 90s;"));
        assert!(conf.contains("proxy_buffering off;"));
    }

